const { it } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');

it('does not render or inject a development banner on WLED pages', () => {
	for (const file of ['common.js', 'index.htm', 'welcome.htm', 'index.css', 'wecker.htm', 'edit.htm', 'liveview.htm', 'liveviewws2D.htm']) {
		const source = fs.readFileSync(`wled00/data/${file}`, 'utf8');
		assert.doesNotMatch(source, /devBanner|__noDevBanner|DEVELOPMENT BUILD/, file);
	}
});

it('does not reserve development-banner space above the main controls', () => {
	const source = fs.readFileSync('wled00/data/index.css', 'utf8');
	assert.doesNotMatch(source, /--dbh/);
	assert.match(source, /--th:\s*70px;/);
	assert.match(source, /--tp:\s*70px;/);
	assert.match(source, /\.wrapper\s*\{[^}]*\btop:\s*0;/);
});
